  1→"use client";
  2→
  3→/**
  4→ * Dashboard route (`/dashboard`).
  5→ *
  6→ * Orchestrates the multi-agent WebSocket hook, sidebar, chat panel, and
  7→ * task panel. Clicking "+" or selecting "New Agent" sets `activeAgentId`
  8→ * to `null`, which shows the spawn input. On spawn, the server responds
  9→ * with `spawned` and the hook auto-selects the new agent.
 10→ *
 11→ * ## Loading states
 12→ *
 13→ * Two loading flags from the hook control the UI:
 14→ * - `initialLoadDone` — false until the first `agent_list` arrives from
 15→ *   the server. While false, the sidebar shows skeleton rows.
 16→ * - `historyLoading` — true when the active agent's message history has
 17→ *   not been fetched yet (lazy loading). The chat shows a "Loading
 18→ *   messages..." indicator until the server responds.
 19→ *
 20→ * Sidebar uses `!initialLoadDone`, chat uses `!initialLoadDone || historyLoading`.
 21→ */
 22→
 23→import { useEffect, useRef, useState } from "react";
 24→import { toast } from "sonner";
 25→import { useWebSocket } from "@/hooks/use-websocket";
 26→import { AgentSidebar } from "@/components/dashboard/agent-sidebar";
 27→import { Chat } from "@/components/dashboard/chat";
 28→import { TaskPanel, type TaskViewMode } from "@/components/dashboard/kanban-board";
 29→import { DiffsPanel } from "@/components/dashboard/diffs-panel";
 30→import { FolderBrowser } from "@/components/dashboard/folder-browser";
 31→import { SfxSettings } from "@/components/dashboard/sfx-settings";
 32→import { Toaster } from "@/components/ui/sonner";
 33→import { TooltipProvider } from "@/components/ui/tooltip";
 34→import { cn } from "@/lib/utils";
 35→
 36→export default function DashboardPage() {
 37→  const {
 38→    connected,
 39→    initialLoadDone,
 40→    historyLoading,
 41→    agents,
 42→    agentOrder,
 43→    activeAgentId,
 44→    setActiveAgentId,
 45→    activeStatus,
 46→    activeMessages,
 47→    activeRawMessages,
 48→    activeModel,
 49→    spawnAgent,
 50→    sendMessage,
 51→    respondToControl,
 52→    respondToUserQuestion,
 53→    killAgent,
 54→    deleteAgent,
 55→    renameAgent,
 56→    clearHistory,
 57→    pinAgent,
 58→    iceboxAgent,
 59→    moveAgent,
 60→    tasks,
 61→    createTask,
 62→    updateTask,
 63→    deleteTask,
 64→    delegateTask,
 65→    workspaces,
 66→    activeWorkspaceId,
 67→    setActiveWorkspaceId,
 68→    createWorkspace,
 69→    renameWorkspace,
 70→    deleteWorkspace,
 71→    browseDirectory,
 72→    directoryListing,
 73→  } = useWebSocket();
 74→
 75→  const [taskView, setTaskView] = useState<"hidden" | TaskViewMode>("hidden");
 76→  const [showDiffs, setShowDiffs] = useState(false);
 77→  const [sidebarOpen, setSidebarOpen] = useState(false);
 78→  const [folderBrowserOpen, setFolderBrowserOpen] = useState(false);
 79→  const [sfxSettingsOpen, setSfxSettingsOpen] = useState(false);
 80→  const [selectedModel, setSelectedModel] = useState("");
 81→
 82→  // Derive initial path from first workspace or fallback to "/"
 83→  const initialBrowsePath = workspaces.length > 0 ? workspaces[0].cwd : "/";
 84→
 85→  // Connection status toasts (skip initial connection)
 86→  const hasConnectedRef = useRef(false);
 87→  useEffect(() => {
 88→    if (connected) {
 89→      if (hasConnectedRef.current) {
 90→        toast.success("Reconnected");
 91→      }
 92→      hasConnectedRef.current = true;
 93→    } else if (hasConnectedRef.current) {
 94→      toast.error("Connection lost");
 95→    }
 96→  }, [connected]);
 97→
 98→  useEffect(() => {
 99→    document.title = "thos — dashboard";
100→  }, []);
101→
102→  return (
103→    <TooltipProvider delayDuration={300}>
104→    <div className="relative flex h-dvh overflow-hidden">
105→      {/* Sidebar backdrop (mobile only) */}
106→      {sidebarOpen && (
107→        <div
108→          className="fixed inset-0 z-40 bg-black/50 md:hidden"
109→          onClick={() => setSidebarOpen(false)}
110→        />
111→      )}
112→
113→      {/* Sidebar drawer */}
114→      <div
115→        className={cn(
116→          "fixed inset-y-0 left-0 z-50 w-56 transition-transform duration-200 ease-in-out md:relative md:z-auto md:translate-x-0 md:transition-none",
117→          sidebarOpen ? "translate-x-0" : "-translate-x-full"
118→        )}
119→      >
120→        <AgentSidebar
121→          agents={agents}
122→          agentOrder={agentOrder}
123→          activeAgentId={activeAgentId}
124→          loading={!initialLoadDone}
125→          onSelect={(id) => {
126→            setActiveAgentId(id);
127→            setSidebarOpen(false);
128→          }}
129→          onNewAgent={() => {
130→            setActiveAgentId(null);
131→            setSidebarOpen(false);
132→          }}
133→          onKill={killAgent}
134→          onDelete={deleteAgent}
135→          onRename={renameAgent}
136→          onClearHistory={clearHistory}
137→          onPin={pinAgent}
