  1→/**
  2→ * Shared type definitions for the thos dashboard.
  3→ *
  4→ * Three categories:
  5→ * 1. **Claude NDJSON protocol** — messages the Claude CLI sends over its
  6→ *    `--sdk-url` WebSocket connection (CLI → WS server).
  7→ * 2. **Browser ↔ Server** — messages exchanged between the React client
  8→ *    and the standalone WS relay server.
  9→ * 3. **UI state** — view-model types consumed by React components.
 10→ *
 11→ * ## Key architecture notes
 12→ *
 13→ * - On browser connect, the server sends `agent_list` + `task_list` only.
 14→ * - Message histories are loaded lazily: the browser sends
 15→ *   `request_history` when selecting an agent, and the server responds
 16→ *   with `message_history` for that single agent.
 17→ * - Live messages for active agents are broadcast via `relay` in real time.
 18→ * - See `server/ws.ts` and `hooks/use-websocket.ts` for implementation.
 19→ */
 20→
 21→// ── Claude NDJSON protocol messages (CLI → server) ────────────────────────
 22→
 23→/**
 24→ * Sent once after the first user prompt is received. Contains session
 25→ * metadata like the model name, working directory, and available tools.
 26→ */
 27→export interface ClaudeSystemInit {
 28→  type: "system";
 29→  subtype: "init";
 30→  session_id: string;
 31→  tools: unknown[];
 32→  mcp_servers: unknown[];
 33→  model: string;
 34→  cwd: string;
 35→}
 36→
 37→/**
 38→ * An assistant turn. `message.content` is an array of content blocks
 39→ * (text, tool_use, tool_result) that may arrive incrementally — each
 40→ * NDJSON line is a complete snapshot of the message so far.
 41→ */
 42→export interface ClaudeAssistant {
 43→  type: "assistant";
 44→  message: {
 45→    id: string;
 46→    role: "assistant";
 47→    content: AssistantContentBlock[];
 48→    model: string;
 49→    stop_reason: string | null;
 50→  };
 51→  session_id: string;
 52→}
 53→
 54→/** A single content block inside an assistant message. */
 55→export type AssistantContentBlock =
 56→  | { type: "text"; text: string }
 57→  | { type: "tool_use"; id: string; name: string; input: Record<string, unknown> }
 58→  | { type: "tool_result"; tool_use_id: string; content: string };
 59→
 60→/**
 61→ * Terminal message for a session. Includes cost/duration metrics.
 62→ * `is_error` is true when `subtype` is `"error"`.
 63→ */
 64→export interface ClaudeResult {
 65→  type: "result";
 66→  subtype: "success" | "error";
 67→  result?: string;
 68→  error?: string;
 69→  session_id: string;
 70→  cost_usd: number;
 71→  total_cost_usd?: number;
 72→  duration_ms: number;
 73→  duration_api_ms: number;
 74→  is_error: boolean;
 75→  num_turns: number;
 76→}
 77→
 78→/**
 79→ * Claude is requesting permission to execute a tool. The dashboard must
 80→ * reply with a `control_response` (allow / deny) before the CLI proceeds.
 81→ *
 82→ * Wire format uses a nested `request` object with `request_id` at the
 83→ * top level for correlation (matches Companion protocol docs).
 84→ */
 85→export interface ClaudeControlRequest {
 86→  type: "control_request";
 87→  request_id: string;
 88→  request: {
 89→    subtype: "can_use_tool";
 90→    tool_name: string;
 91→    input: Record<string, unknown>;
 92→    tool_use_id?: string;
 93→    description?: string;
 94→  };
 95→  session_id?: string;
 96→}
 97→
 98→/**
 99→ * Hook lifecycle events emitted during CLI startup. `hook_response` is
100→ * the signal that the CLI is ready to receive the first user prompt.
101→ */
102→export interface ClaudeSystemHook {
103→  type: "system";
104→  subtype: "hook_started" | "hook_response";
105→  session_id?: string;
106→}
107→
108→/** Discriminated union of all known Claude NDJSON message shapes. */
109→export type ClaudeMessage =
110→  | ClaudeSystemInit
111→  | ClaudeAssistant
112→  | ClaudeResult
113→  | ClaudeControlRequest
114→  | ClaudeSystemHook
115→  | { type: string; subtype?: string; [key: string]: unknown };
116→
117→// ── Workspaces ───────────────────────────────────────────────────────────
118→
119→/** A workspace represents a project directory. */
120→export interface Workspace {
121→  id: string;
122→  name: string;
123→  cwd: string;
124→  createdAt: number;
125→}
126→
127→/** A directory entry returned by the server-side folder browser. */
128→export interface DirectoryEntry {
129→  name: string;
130→  path: string;
131→}
132→
133→// ── Browser ↔ Server messages ─────────────────────────────────────────────
134→
135→/** Browser asks the server to spawn a new Claude CLI process. */
136→export interface BrowserSpawn {
137→  type: "spawn";
138→  prompt: string;
139→  workspaceId?: string;
140→  /** Optional model override (e.g. "claude-opus-4-20250514", "qwen3-coder"). */
141→  model?: string;
142→}
143→
144→/** Browser sends a follow-up message to an already-running Claude session. */
145→export interface BrowserSendMessage {
146→  type: "send_message";
147→  agentId: string;
148→  content: string;
149→}
150→
151→/** Browser responds to a tool approval request (allow or deny). */
152→export interface BrowserControlResponse {
153→  type: "control_response";
154→  agentId: string;
155→  request_id: string;
156→  allow: boolean;
157→}
158→
159→/** Browser asks the server to kill a running agent's tmux session + CLI. */
160→export interface BrowserKillAgent {
161→  type: "kill_agent";
162→  agentId: string;
163→}
164→
165→/** Browser asks the server to permanently delete an agent. */
166→export interface BrowserDeleteAgent {
167→  type: "delete_agent";
168→  agentId: string;
169→}
170→
171→/** Browser asks the server to rename an agent. */
172→export interface BrowserRenameAgent {
173→  type: "rename_agent";
174→  agentId: string;
175→  label: string;
176→}
177→
178→/** Browser asks the server to clear an agent's message history. */
179→export interface BrowserClearHistory {
180→  type: "clear_history";
181→  agentId: string;
182→}
183→
184→/** Browser asks the server to pin or unpin an agent. */
185→export interface BrowserPinAgent {
186→  type: "pin_agent";
187→  agentId: string;
188→  pinned: boolean;
189→}
190→
191→/** Browser asks the server to icebox or un-icebox an agent. */
192→export interface BrowserIceboxAgent {
193→  type: "icebox_agent";
194→  agentId: string;
195→  iceboxed: boolean;
196→}
197→
198→/** Browser asks the server to move an agent to a different workspace. */
199→export interface BrowserMoveAgent {
200→  type: "move_agent";
201→  agentId: string;
202→  workspaceId: string | null;
203→}
204→
205→/** Browser requests message history for a specific agent (lazy loading). */
206→export interface BrowserRequestHistory {
207→  type: "request_history";
208→  agentId: string;
209→}
210→
211→/** Browser asks the server to create a new task. */
212→export interface BrowserCreateTask {
213→  type: "create_task";
214→  title: string;
215→  description: string;
216→  priority: TaskPriority;
217→}
218→
219→/** Browser asks to update a task's fields. */
220→export interface BrowserUpdateTask {
221→  type: "update_task";
222→  taskId: string;
223→  updates: Partial<Pick<Task, "title" | "description" | "status" | "priority">>;
224→}
225→
226→/** Browser asks to delete a task. */
227→export interface BrowserDeleteTask {
228→  type: "delete_task";
229→  taskId: string;
230→}
231→
232→/** Browser asks to delegate a task to a new Claude agent. */
233→export interface BrowserDelegateTask {
234→  type: "delegate_task";
235→  taskId: string;
236→}
237→
238→/** Browser tells the server which workspace to scope to. */
239→export interface BrowserSetWorkspace {
240→  type: "set_workspace";
241→  workspaceId: string | null;
242→}
243→
244→/** Browser asks the server to create a new workspace. */
245→export interface BrowserCreateWorkspace {
246→  type: "create_workspace";
247→  name: string;
248→  cwd: string;
249→}
250→
251→/** Browser asks to rename a workspace. */
252→export interface BrowserRenameWorkspace {
253→  type: "rename_workspace";
254→  workspaceId: string;
255→  name: string;
256→}
257→
258→/** Browser asks to delete a workspace. */
259→export interface BrowserDeleteWorkspace {
260→  type: "delete_workspace";
261→  workspaceId: string;
262→}
263→
264→/** Browser asks to browse a directory on the server. */
265→export interface BrowserBrowseDirectory {
266→  type: "browse_directory";
267→  path: string;
268→}
269→
270→/** Union of all messages the browser can send to the WS server. */
271→export type BrowserMessage =
272→  | BrowserSpawn
273→  | BrowserSendMessage
274→  | BrowserControlResponse
275→  | BrowserKillAgent
276→  | BrowserDeleteAgent
277→  | BrowserRenameAgent
278→  | BrowserClearHistory
279→  | BrowserPinAgent
280→  | BrowserIceboxAgent
281→  | BrowserMoveAgent
282→  | BrowserRequestHistory
283→  | BrowserCreateTask
284→  | BrowserUpdateTask
285→  | BrowserDeleteTask
286→  | BrowserDelegateTask
287→  | BrowserSetWorkspace
288→  | BrowserCreateWorkspace
289→  | BrowserRenameWorkspace
290→  | BrowserDeleteWorkspace
291→  | BrowserBrowseDirectory;
292→
293→/** Server relays a raw Claude NDJSON message to the browser. */
294→export interface ServerRelay {
295→  type: "relay";
296→  agentId: string;
297→  message: ClaudeMessage;
298→}
299→
300→/** Server notifies the browser of an agent status change. */
301→export interface ServerStatus {
302→  type: "status";
303→  agentId: string;
304→  status: AgentStatus;
305→}
306→
307→/** Server reports an error (e.g. no active session, process crash). */
308→export interface ServerError {
309→  type: "error";
310→  agentId: string;
311→  error: string;
312→}
313→
314→/** Summary of an agent for the sidebar. */
315→export interface AgentInfo {
316→  agentId: string;
317→  status: AgentStatus;
318→  tmuxSession: string | null;
319→  label: string;
320→  createdAt: number;
321→  workspaceId: string | null;
322→  /** Model name reported by system/init, or the model requested at spawn time. */
323→  model?: string | null;
324→  /** Whether this agent is pinned to the top of the sidebar. */
325→  pinned?: boolean;
326→  /** Whether this agent is in the icebox (parked for later). */
327→  iceboxed?: boolean;
328→}
329→
330→/** Server sends the full list of agents after every state change. */
331→export interface ServerAgentList {
332→  type: "agent_list";
333→  agents: AgentInfo[];
334→}
335→
336→/** Server confirms a new agent was spawned and assigns its ID. */
337→export interface ServerSpawned {
338→  type: "spawned";
339→  agentId: string;
340→}
341→
342→/** Server sends full message history for an agent (in response to `request_history`). */
343→export interface ServerMessageHistory {
344→  type: "message_history";
345→  agentId: string;
346→  messages: ServerMessage[];
347→}
348→
349→/** CLI WebSocket disconnected (process may have crashed or exited). */
