 308→/** Build the full task list sorted by creation time (newest first), optionally filtered by workspace. */
 309→function buildTaskList(workspaceId?: string | null): Task[] {
 310→  let list = Array.from(tasks.values());
 311→  if (workspaceId !== undefined && workspaceId !== null) {
 312→    list = list.filter((t) => t.workspaceId === workspaceId);
