 343→/** Build a snapshot of all agents for the sidebar, optionally filtered by workspace. */
 344→function buildAgentList(workspaceId?: string | null): AgentInfo[] {
 345→  let list = Array.from(agents.values());
 346→  if (workspaceId !== undefined && workspaceId !== null) {
 347→    list = list.filter((a) => a.workspaceId === workspaceId);
 348→  }
 349→  return list.map((a) => ({
 350→    agentId: a.agentId,
 351→    status: a.status,
 352→    tmuxSession: a.tmuxSession,
 353→    label: a.label,
 354→    createdAt: a.createdAt,
 355→    workspaceId: a.workspaceId,
 356→    model: a.model,
 357→    pinned: a.pinned || undefined,
