266→/** Console logger with [thos] prefix for easy filtering. */
267→function log(...args: unknown[]) {
268→  console.log("[thos-ws]", ...args);
269→}
270→
271→export function useWebSocket() {
272→  const wsRef = useRef<WebSocket | null>(null);
273→  const reconnectTimer = useRef<ReturnType<typeof setTimeout> | null>(null);
274→  /** Set to true during cleanup to prevent onclose from scheduling reconnects. */
275→  const closingRef = useRef(false);
276→  const [connected, setConnected] = useState(false);
277→  /** True once we've received the initial agent_list from the server. */
278→  const [initialLoadDone, setInitialLoadDone] = useState(false);
279→
280→  // Multi-agent state
281→  const [agents, setAgents] = useState<Map<string, AgentClientState>>(new Map());
282→  const [agentOrder, setAgentOrder] = useState<string[]>([]);
283→  const [activeAgentId, setActiveAgentId] = useState<string | null>(null);
284→
285→  // Task state
286→  const [tasks, setTasks] = useState<Task[]>([]);
287→
288→  // Workspace state
289→  const [workspaces, setWorkspaces] = useState<Workspace[]>([]);
290→  const [activeWorkspaceId, setActiveWorkspaceIdState] = useState<string | null>(null);
291→  const [directoryListing, setDirectoryListing] = useState<{ path: string; entries: DirectoryEntry[] } | null>(null);
292→
293→  // Per-agent deduplication: track count of processed messages per agent
294→  // to avoid duplicating messages already in local state during history replay.
295→  const processedCountRef = useRef<Map<string, number>>(new Map());
296→
297→  // Track which agents have had their history loaded (lazy loading).
298→  const [loadedAgents, setLoadedAgents] = useState<Set<string>>(new Set());
299→
300→  /** Immutably update a single agent's state in the Map. */
301→  const updateAgent = useCallback(
302→    (agentId: string, updater: (prev: AgentClientState) => AgentClientState) => {
303→      setAgents((prev) => {
304→        const existing = prev.get(agentId);
305→        if (!existing) return prev;
306→        const next = new Map(prev);
307→        next.set(agentId, updater(existing));
308→        return next;
309→      });
310→    },
311→    []
312→  );
313→
314→  const connect = useCallback(() => {
315→    if (wsRef.current?.readyState === WebSocket.OPEN) return;
316→    if (wsRef.current) {
317→      wsRef.current.close();
318→      wsRef.current = null;
319→    }
320→
321→    // Reset dedup counts on new connection — server will send fresh history
322→    processedCountRef.current.clear();
323→    setInitialLoadDone(false);
324→    setLoadedAgents(new Set());
325→
326→    log("connecting to", WS_URL);
327→    const ws = new WebSocket(WS_URL);
328→    wsRef.current = ws;
329→
330→    ws.onopen = () => {
331→      log("connected");
332→      setConnected(true);
333→    };
334→
335→    ws.onclose = () => {
336→      log("disconnected, closingRef =", closingRef.current);
337→      setConnected(false);
338→      wsRef.current = null;
339→      // Don't reconnect if the close was triggered by cleanup (e.g. strict mode unmount)
340→      if (closingRef.current) return;
341→      // Reconnection guard: clear any existing timer before scheduling
342→      if (reconnectTimer.current) clearTimeout(reconnectTimer.current);
343→      log("scheduling reconnect in 2s");
344→      reconnectTimer.current = setTimeout(() => connect(), 2000);
345→    };
346→
347→    ws.onerror = (e) => {
348→      log("error", e);
349→      // onclose will fire after onerror, which triggers reconnect
350→    };
351→
352→    ws.onmessage = (event) => {
353→      let data: ServerMessage;
354→      try {
355→        data = JSON.parse(event.data as string);
356→      } catch {
357→        return;
358→      }
359→
360→      log("←", data.type, "agentId" in data ? (data as { agentId: string }).agentId : "");
361→
362→      // ── workspace_list: full workspace list from server ──
363→      if (data.type === "workspace_list") {
364→        const wsList = (data as { workspaces: Workspace[] }).workspaces;
365→        log("workspace_list:", wsList.length, "workspaces");
366→        setWorkspaces(wsList);
367→        return;
368→      }
369→
370→      // ── directory_listing: response to browse_directory ──
371→      if (data.type === "directory_listing") {
372→        const listing = data as { path: string; entries: DirectoryEntry[] };
373→        log("directory_listing:", listing.path, listing.entries.length, "entries");
374→        setDirectoryListing({ path: listing.path, entries: listing.entries });
375→        return;
376→      }
377→
378→      // ── task_list: full task list from server ──
379→      if (data.type === "task_list") {
380→        log("task_list:", (data as ServerTaskList).tasks.length, "tasks");
381→        setTasks((data as ServerTaskList).tasks);
382→        return;
383→      }
384→
385→      // ── task_updated: single task changed ──
386→      if (data.type === "task_updated") {
387→        const updated = (data as ServerTaskUpdated).task;
388→        setTasks((prev) => prev.map((t) => (t.id === updated.id ? updated : t)));
389→        return;
390→      }
391→
392→      // ── task_deleted: remove task ──
393→      if (data.type === "task_deleted") {
394→        const deletedId = (data as ServerTaskDeleted).taskId;
395→        setTasks((prev) => prev.filter((t) => t.id !== deletedId));
396→        return;
397→      }
398→
399→      // ── message_history: replay full history from server ──
400→      if (data.type === "message_history") {
401→        const historyMsg = data as ServerMessageHistory;
402→        const agentId = historyMsg.agentId;
403→        const serverMessages = historyMsg.messages;
404→        log("message_history:", agentId, serverMessages.length, "raw msgs");
405→
406→        // Convert all server messages to ChatMessages + extract raw Claude messages
407→        const chatMessages: ChatMessage[] = [];
408→        const rawMessages: ClaudeMessage[] = [];
409→        for (const sm of serverMessages) {
410→          if (sm.type === "relay") {
411→            rawMessages.push(sm.message);
412→          }
413→          const cm = relayChatMessage(agentId, sm);
414→          if (cm) chatMessages.push(cm);
415→        }
416→        log("message_history:", agentId, "→", chatMessages.length, "chat msgs,", rawMessages.length, "raw");
417→
418→        // Always replace local messages with server history (source of truth).
419→        setAgents((prev) => {
420→          const existing = prev.get(agentId);
421→          if (!existing) {
422→            log("message_history:", agentId, "agent not in map yet, creating");
423→            const next = new Map(prev);
424→            next.set(agentId, {
425→              status: "idle",
426→              messages: chatMessages,
427→              rawMessages,
428→              label: "",
429→              tmuxSession: null,
430→              createdAt: 0,
431→            });
432→            return next;
433→          }
434→          const next = new Map(prev);
435→          next.set(agentId, { ...existing, messages: chatMessages, rawMessages });
436→          return next;
437→        });
438→
439→        processedCountRef.current.set(agentId, chatMessages.length);
440→        setLoadedAgents((prev) => {
441→          if (prev.has(agentId)) return prev;
442→          const next = new Set(prev);
443→          next.add(agentId);
444→          return next;
445→        });
446→        return;
447→      }
448→
449→      // ── history_cleared: wipe local messages for this agent ──
450→      if (data.type === "history_cleared") {
451→        updateAgent(data.agentId, (prev) => ({
452→          ...prev,
453→          messages: [],
454→          rawMessages: [],
455→        }));
456→        processedCountRef.current.set(data.agentId, 0);
457→        return;
458→      }
459→
460→      // ── cli_disconnected: show system message ──
461→      if (data.type === "cli_disconnected") {
462→        updateAgent(data.agentId, (prev) => ({
463→          ...prev,
464→          messages: [
465→            ...prev.messages,
466→            {
467→              id: nextId(),
468→              role: "system",
469→              content: "CLI session ended",
470→              timestamp: Date.now(),
471→            },
472→          ],
473→        }));
474→        return;
475→      }
476→
477→      // ── cli_connected: show system message ──
478→      if (data.type === "cli_connected") {
479→        updateAgent(data.agentId, (prev) => ({
480→          ...prev,
481→          messages: [
482→            ...prev.messages,
483→            {
484→              id: nextId(),
485→              role: "system",
486→              content: "CLI reconnected",
487→              timestamp: Date.now(),
488→            },
489→          ],
490→        }));
491→        return;
492→      }
493→
494→      // ── agent_list: reconcile sidebar state from server ──
495→      if (data.type === "agent_list") {
496→        const serverAgents = data.agents as AgentInfo[];
497→        log("agent_list:", serverAgents.length, "agents:", serverAgents.map((a) => `${a.agentId}(${a.status})`).join(", "));
498→        setAgents((prev) => {
499→          const next = new Map(prev);
500→          const serverIds = new Set(serverAgents.map((a) => a.agentId));
501→
502→          // Update or add agents from server
503→          for (const info of serverAgents) {
504→            const existing = next.get(info.agentId);
505→            if (existing) {
506→              next.set(info.agentId, {
507→                ...existing,
508→                status: info.status,
509→                tmuxSession: info.tmuxSession,
510→                label: info.label,
511→                model: info.model ?? existing.model,
512→                pinned: info.pinned ?? false,
513→                iceboxed: info.iceboxed ?? false,
514→                workspaceId: info.workspaceId,
515→              });
516→            } else {
517→              next.set(info.agentId, {
518→                status: info.status,
519→                messages: [],
520→                rawMessages: [],
521→                label: info.label,
522→                tmuxSession: info.tmuxSession,
523→                createdAt: info.createdAt,
524→                model: info.model ?? undefined,
525→                pinned: info.pinned ?? false,
526→                iceboxed: info.iceboxed ?? false,
527→                workspaceId: info.workspaceId,
528→              });
529→            }
530→          }
531→
532→          // Remove agents no longer on the server
533→          for (const id of next.keys()) {
534→            if (!serverIds.has(id)) {
535→              next.delete(id);
536→            }
537→          }
538→
539→          return next;
540→        });
541→        setAgentOrder(serverAgents.map((a) => a.agentId));
542→        setInitialLoadDone(true);
543→
544→        // Auto-select the first agent on initial load when nothing is selected
545→        setActiveAgentId((prev) => {
546→          if (prev !== null) return prev;
547→          if (serverAgents.length === 0) return null;
548→          return serverAgents[0].agentId;
549→        });
550→        return;
551→      }
552→
553→      // ── spawned: auto-select the newly created agent ──
554→      if (data.type === "spawned") {
555→        setActiveAgentId(data.agentId);
556→        return;
557→      }
558→
559→      // ── status: update a specific agent's status ──
560→      if (data.type === "status") {
561→        updateAgent(data.agentId, (prev) => ({ ...prev, status: data.status }));
562→        return;
563→      }
564→
565→      // ── error: append to agent's message list ──
566→      if (data.type === "error") {
567→        sfxError();
568→        updateAgent(data.agentId, (prev) => ({
569→          ...prev,
570→          messages: [
571→            ...prev.messages,
572→            {
573→              id: nextId(),
574→              role: "system",
575→              content: `Error: ${data.error}`,
576→              timestamp: Date.now(),
577→            },
578→          ],
579→        }));
580→        // Track processed count for dedup
581→        processedCountRef.current.set(
582→          data.agentId,
583→          (processedCountRef.current.get(data.agentId) ?? 0) + 1
584→        );
585→        return;
586→      }
587→
588→      // ── relay: append claude message to agent's history ──
589→      if (data.type === "relay") {
590→        const agentId = data.agentId;
591→        const rawMsg = data.message;
592→        const chatMsg = relayChatMessage(agentId, data);
593→
594→        // SFX: play a sound for each tool call in the message
595→        if (chatMsg?.toolCalls?.length) {
596→          // Play SFX for the first mapped tool (avoids overlapping sounds in multi-tool messages)
597→          const first = chatMsg.toolCalls.find((tc) => tc.name);
598→          if (first) sfxTool(first.name);
599→        }
600→
601→        // SFX: result done / error
602→        if (rawMsg.type === "result") {
603→          const result = rawMsg as ClaudeResult;
604→          if (result.is_error) sfxError();
605→          else sfxDone();
606→        }
607→
608→        // SFX: control request (tool approval / question)
609→        if (rawMsg.type === "control_request") {
610→          sfxQuestion();
611→        }
612→
613→        // SFX: session start
614→        if (rawMsg.type === "system" && (rawMsg as { subtype?: string }).subtype === "init") {
615→          sfxBegin();
616→        }
617→
618→        // Capture model from system/init
619→        const initModel =
620→          rawMsg.type === "system" && (rawMsg as { subtype?: string }).subtype === "init"
621→            ? (rawMsg as ClaudeSystemInit).model
622→            : undefined;
623→
624→        updateAgent(agentId, (prev) => ({
625→          ...prev,
626→          rawMessages: [...prev.rawMessages, rawMsg],
627→          messages: chatMsg ? [...prev.messages, chatMsg] : prev.messages,
628→          ...(initModel ? { model: initModel } : {}),
629→        }));
630→        if (chatMsg) {
631→          // Track processed count for dedup
632→          processedCountRef.current.set(
633→            agentId,
634→            (processedCountRef.current.get(agentId) ?? 0) + 1
635→          );
636→        }
637→        return;
638→      }
639→    };
640→  }, [updateAgent]);
641→
642→  useEffect(() => {
643→    closingRef.current = false;
644→    connect();
645→    return () => {
646→      closingRef.current = true;
647→      if (reconnectTimer.current) clearTimeout(reconnectTimer.current);
648→      wsRef.current?.close();
649→    };
650→  }, [connect]);
651→
652→  const send = useCallback((data: object) => {
653→    if (wsRef.current?.readyState === WebSocket.OPEN) {
654→      wsRef.current.send(JSON.stringify(data));
655→    }
656→  }, []);
657→
658→  // Request history for the active agent if not already loaded.
659→  useEffect(() => {
660→    if (!activeAgentId || loadedAgents.has(activeAgentId)) return;
661→    log("requesting history for", activeAgentId);
662→    send({ type: "request_history", agentId: activeAgentId });
663→  }, [activeAgentId, loadedAgents, send]);
664→
665→  const spawnAgent = useCallback(
666→    (prompt: string, model?: string) => {
667→      send({ type: "spawn", prompt, ...(model ? { model } : {}) });
668→    },
669→    [send]
670→  );
671→
672→  const sendMessage = useCallback(
673→    (content: string) => {
674→      if (!activeAgentId) return;
675→      // Optimistically add user message to local state
676→      updateAgent(activeAgentId, (prev) => ({
677→        ...prev,
678→        messages: [
679→          ...prev.messages,
680→          {
681→            id: nextId(),
682→            role: "user",
683→            content,
684→            timestamp: Date.now(),
685→          },
686→        ],
687→      }));
688→      send({ type: "send_message", agentId: activeAgentId, content });
689→      sfxSend();
690→    },
691→    [send, activeAgentId, updateAgent]
692→  );
693→
694→  const respondToControl = useCallback(
695→    (requestId: string, allow: boolean) => {
696→      if (!activeAgentId) return;
697→      send({ type: "control_response", agentId: activeAgentId, request_id: requestId, allow });
698→      updateAgent(activeAgentId, (prev) => ({
699→        ...prev,
700→        messages: prev.messages.map((m) =>
701→          m.controlRequest?.id === requestId
702→            ? { ...m, controlRequest: { ...m.controlRequest, resolved: true, allowed: allow } }
703→            : m
704→        ),
705→      }));
706→    },
707→    [send, activeAgentId, updateAgent]
708→  );
709→
710→  /** Respond to an AskUserQuestion control request with the user's selections. */
711→  const respondToUserQuestion = useCallback(
712→    (requestId: string, answers: Record<string, string>) => {
713→      if (!activeAgentId) return;
714→      send({
715→        type: "control_response",
716→        agentId: activeAgentId,
717→        request_id: requestId,
718→        allow: true,
719→        answers,
720→      });
721→      updateAgent(activeAgentId, (prev) => ({
722→        ...prev,
723→        messages: prev.messages.map((m) =>
724→          m.userQuestion?.requestId === requestId
725→            ? { ...m, userQuestion: { ...m.userQuestion, resolved: true } }
726→            : m
727→        ),
728→      }));
729→    },
730→    [send, activeAgentId, updateAgent]
731→  );
732→
733→  // ── Agent management actions ──────────────────────────────────────────────
734→
735→  const killAgent = useCallback(
736→    (agentId: string) => {
737→      send({ type: "kill_agent", agentId });
738→    },
739→    [send]
740→  );
741→
742→  const deleteAgent = useCallback(
743→    (agentId: string) => {
744→      send({ type: "delete_agent", agentId });
745→      // Deselect if we just deleted the active agent
746→      setActiveAgentId((prev) => (prev === agentId ? null : prev));
747→    },
748→    [send]
749→  );
750→
751→  const renameAgent = useCallback(
752→    (agentId: string, label: string) => {
753→      send({ type: "rename_agent", agentId, label });
754→    },
755→    [send]
756→  );
757→
758→  const clearHistory = useCallback(
759→    (agentId: string) => {
760→      send({ type: "clear_history", agentId });
761→    },
762→    [send]
763→  );
764→
765→  const pinAgent = useCallback(
766→    (agentId: string, pinned: boolean) => {
767→      send({ type: "pin_agent", agentId, pinned });
768→    },
769→    [send]
770→  );
771→
772→  const iceboxAgent = useCallback(
773→    (agentId: string, iceboxed: boolean) => {
774→      send({ type: "icebox_agent", agentId, iceboxed });
775→    },
776→    [send]
777→  );
778→
779→  const moveAgent = useCallback(
780→    (agentId: string, workspaceId: string | null) => {
781→      send({ type: "move_agent", agentId, workspaceId });
782→    },
783→    [send]
784→  );
785→
786→  // ── Task actions ──────────────────────────────────────────────────────────
787→
788→  const createTask = useCallback(
789→    (title: string, description: string, priority: TaskPriority) => {
790→      send({ type: "create_task", title, description, priority });
791→    },
792→    [send]
793→  );
794→
795→  const updateTask = useCallback(
796→    (taskId: string, updates: Partial<Pick<Task, "title" | "description" | "status" | "priority">>) => {
797→      send({ type: "update_task", taskId, updates });
798→    },
799→    [send]
800→  );
801→
802→  const deleteTask = useCallback(
803→    (taskId: string) => {
804→      send({ type: "delete_task", taskId });
805→    },
806→    [send]
807→  );
808→
809→  const delegateTask = useCallback(
810→    (taskId: string) => {
811→      send({ type: "delegate_task", taskId });
812→    },
813→    [send]
814→  );
815→
816→  // ── Workspace actions ──────────────────────────────────────────────────────
817→
818→  const setActiveWorkspaceId = useCallback(
819→    (workspaceId: string | null) => {
820→      setActiveWorkspaceIdState(workspaceId);
821→      send({ type: "set_workspace", workspaceId });
822→    },
