 35→export function StatusBar({
 36→  connected,
 37→  status,
 38→  agentLabel,
 39→  activeModel,
 40→  selectedModel,
 41→  onModelChange,
 42→  showRaw,
 43→  onToggleRaw,
 44→  showTasks,
 45→  onToggleTasks,
 46→  showDiffs,
 47→  onToggleDiffs,
 48→  onToggleSidebar,
 49→  onOpenSfxSettings,
 50→}: {
 51→  connected: boolean;
 52→  status: AgentStatus;
 53→  agentLabel?: string | null;
 54→  activeModel?: string | null;
 55→  selectedModel?: string;
 56→  onModelChange?: (model: string) => void;
 57→  showRaw?: boolean;
 58→  onToggleRaw?: () => void;
 59→  showTasks?: boolean;
 60→  onToggleTasks?: () => void;
 61→  showDiffs?: boolean;
 62→  onToggleDiffs?: () => void;
 63→  onToggleSidebar?: () => void;
 64→  onOpenSfxSettings?: () => void;
 65→}) {
 66→  const [dropdownOpen, setDropdownOpen] = useState(false);
 67→  const [customInput, setCustomInput] = useState("");
 68→  const [showCustom, setShowCustom] = useState(false);
 69→  const dropdownRef = useRef<HTMLDivElement>(null);
 70→  const customInputRef = useRef<HTMLInputElement>(null);
 71→
 72→  // Close dropdown on click-outside or Escape
 73→  useEffect(() => {
 74→    if (!dropdownOpen) return;
 75→    function handleClick(e: MouseEvent) {
 76→      if (dropdownRef.current && !dropdownRef.current.contains(e.target as Node)) {
 77→        setDropdownOpen(false);
 78→        setShowCustom(false);
 79→      }
 80→    }
 81→    function handleKey(e: KeyboardEvent) {
 82→      if (e.key === "Escape") {
 83→        setDropdownOpen(false);
 84→        setShowCustom(false);
 85→      }
 86→    }
 87→    document.addEventListener("mousedown", handleClick);
 88→    document.addEventListener("keydown", handleKey);
 89→    return () => {
 90→      document.removeEventListener("mousedown", handleClick);
 91→      document.removeEventListener("keydown", handleKey);
 92→    };
 93→  }, [dropdownOpen]);
 94→
