```typescript
/**
 * Extract the most recent tool activity from a Claude assistant message.
 * Returns the last tool_use block's name + a short detail string, or null
 * if the message contains no tool_use blocks.
 */
function extractActivity(
  msg: ClaudeMessage
): { toolName: string; detail: string } | null {
  if (msg.type !== "assistant") return null;
  const blocks = (msg as ClaudeAssistant).message?.content;
  if (!blocks || !Array.isArray(blocks)) return null;

  // Find the last tool_use block (most recent activity in cumulative snapshot)
  let lastToolUse: { name: string; input: Record<string, unknown> } | null = null;
  for (const b of blocks) {
    if (b.type === "tool_use") {
      lastToolUse = b as { name: string; input: Record<string, unknown> };
    }
  }
  if (!lastToolUse) return null;

  const detail = extractToolDetail(lastToolUse.name, lastToolUse.input);
  return { toolName: lastToolUse.name, detail };
}

/**
 * Derive a short human-readable detail string from a tool's input.
 * Extracts file paths, commands, patterns, etc. based on the tool name.
 */
function extractToolDetail(
  toolName: string,
  input: Record<string, unknown>
): string {
  switch (toolName) {
    case "Read":
    case "Write":
    case "Edit":
    case "MultiEdit": {
      const fp = input.file_path as string | undefined;
      if (fp) return fp.split("/").pop() ?? fp;
      return "";
    }
    case "Bash": {
      const cmd = input.command as string | undefined;
      if (cmd) {
        // Show first 40 chars of the command
        return cmd.length > 40 ? cmd.slice(0, 37) + "..." : cmd;
      }
      return "";
    }
    case "Glob": {
      const pattern = input.pattern as string | undefined;
      return pattern ?? "";
    }
    case "Grep": {
      const pattern = input.pattern as string | undefined;
      return pattern ?? "";
    }
    case "WebFetch": {
      const url = input.url as string | undefined;
      if (url) {
        try {
          return new URL(url).hostname;
        } catch {
          return url.slice(0, 30);
        }
      }
      return "";
    }
    case "TodoWrite":
    case "Task":
      return "";
    default:
      return "";
  }
}
```

**Rationale:** This function uses the same tool name taxonomy as `TOOL_COLORS` in `condensed-tool-group.tsx`. The detail extraction is tool-specific: file tools show the basename, Bash shows a truncated command, Grep/Glob show the pattern, WebFetch shows the hostname. For unknown tools it returns an empty string, which the UI handles gracefully.

**Important design decision:** We look at the *last* `tool_use` block in the content array, not the first. Claude's NDJSON protocol sends cumulative snapshots, meaning each assistant message contains all content blocks accumulated so far. The last `tool_use` block represents the most recent tool invocation, which is the correct "current activity."

