function renderAgentRow(id: string, dimmed: boolean) {
  const agent = agents.get(id);
  if (!agent) return null;
  const isActive = id === activeAgentId;
  const showActivity = agent.currentActivity && (agent.status === "thinking" || agent.status === "connected");
  return (
    <div
      key={id}
      onClick={() => onSelect(id)}
      onContextMenu={(e) => handleContextMenu(e, id)}
      className={cn(
        "group flex w-full cursor-pointer items-start gap-0.5 px-3 py-2 text-left text-xs transition-colors",
        isActive ? "bg-sidebar-accent" : "hover:bg-sidebar-accent/50",
        dimmed && "opacity-60"
      )}
    >
      <div className="flex min-w-0 flex-1 flex-col gap-0.5">
        {/* Row 1: status dot + label + icons */}
        <span className="flex items-center gap-2">
          <span className={cn("inline-block size-2 shrink-0 rounded-full", STATUS_DOT[agent.status])} />
          {renamingId === id ? (
            <RenameInput
              initialValue={agent.label}
              onConfirm={(label) => { onRename(id, label); setRenamingId(null); }}
              onCancel={() => setRenamingId(null)}
            />
          ) : (
            <Tip text={agent.label || "new agent"} side="right">
              <span className="truncate">{agent.label || "new agent"}</span>
            </Tip>
          )}
          {agent.pinned && <Pin className="size-2.5 shrink-0 text-muted-foreground" />}
          {agent.iceboxed && <Snowflake className="size-2.5 shrink-0 text-muted-foreground" />}
        </span>

        {/* Row 2: agent ID + workspace */}
        <span className="pl-4 text-[10px] text-muted-foreground truncate font-mono">
          {id}
          {(() => {
            const ws = workspaces.find((w) => w.id === agent.workspaceId);
            return ws ? <span className="opacity-60"> · {ws.name}</span> : null;
          })()}
        </span>

        {/* Row 3: current activity indicator (only for working agents) */}
        {showActivity && agent.currentActivity && (
          <span className="flex items-center gap-1.5 pl-4 text-[10px] text-muted-foreground truncate">
            <span
              className={cn(
                "inline-block size-1.5 shrink-0 rounded-full animate-pulse",
                TOOL_COLORS[agent.currentActivity.toolName] ?? "bg-muted-foreground/50"
              )}
            />
            <span className="font-mono shrink-0">{agent.currentActivity.toolName}</span>
            {agent.currentActivity.detail && (
              <Tip text={agent.currentActivity.detail} side="right">
                <span className="truncate opacity-70">{agent.currentActivity.detail}</span>
              </Tip>
            )}
          </span>
        )}
      </div>

      {/* Kebab menu button */}
      <button
        onClick={(e) => handleMenuButton(e, id)}
        className="shrink-0 rounded p-0.5 opacity-0 transition-opacity hover:bg-sidebar-accent group-hover:opacity-100"
        aria-label="Agent menu"
      >
        <EllipsisVertical className="size-3.5 text-muted-foreground" />
      </button>
    </div>
  );
}
```

**Key design decisions for the activity indicator:**

1. **Dot size:** `size-1.5` (6px) -- smaller than the status dot (`size-2` = 8px) to create visual hierarchy. The activity dot is subordinate information.

2. **Pulse animation:** The dot uses `animate-pulse` to subtly convey that the tool is actively running. This reuses the same Tailwind animation already used for `spawning` and `thinking` status dots.

3. **Color source:** `TOOL_COLORS[agent.currentActivity.toolName]` with a `bg-muted-foreground/50` fallback for unknown tools. This matches the exact color scheme from the condensed tool group.

4. **Tool name in monospace:** `font-mono` matches the existing monospace styling used for agent IDs.

5. **Detail with tooltip:** The detail string (filename, command, etc.) is truncated with `truncate` and wrapped in `<Tip>` so the full text is visible on hover. This is critical for the 224px sidebar width.

6. **Left padding:** `pl-4` aligns the activity indicator with the agent ID line above it (both are indented past the status dot).

7. **Conditional render:** `showActivity` is false for archived/disconnected agents, preventing stale activity indicators from appearing.

